WITH valid_orders AS (SELECT * FROM orders WHERE status = 'SHIPPED' AND shipping_fee <= 10 AND amount > 510), ChannelSummary AS (SELECT channel, status, SORT_ARRAY(COLLECT_SET(status)) status_list, SUM(CASE WHEN status = 'PENDING' THEN 1 ELSE 0 END) pending_count FROM valid_orders GROUP BY channel, status) SELECT channel, status_list, pending_count FROM ChannelSummary WHERE pending_count >= 59 ORDER BY pending_count DESC, channel
